// Bluevia – F7 – موضوعات المحتوى التلقائية
const now = new Date();
const day = now.getDay();
const month = now.getMonth() + 1;

const dayTopics = {
  0: [ // الأحد – إسطنبول وجمال البوسفور
    { topic: 'أفضل 10 أنشطة سياحية في إسطنبول 2026', type: 'educational', angle: 'istanbul_intro' },
    { topic: 'سهرة البوسفور المسائية: تجربة ملكية لا تُنسى', type: 'lifestyle', angle: 'bosphorus_night' },
  ],
  1: [ // الاثنين – طرابزون والشمال التركي
    { topic: 'لماذا يفضل الخليجيون قضاء الصيف في طرابزون؟', type: 'educational', angle: 'trabzon_gulf' },
    { topic: 'أوزنجول: جنة الأرض في قلب الشمال التركي', type: 'nature', angle: 'uzungol_beauty' },
  ],
  2: [ // الثلاثاء – السياحة العلاجية
    { topic: 'دليلك الشامل لزراعة الشعر في أفضل مراكز إسطنبول', type: 'educational', angle: 'medical_hair' },
    { topic: 'أفضل عيادات التجميل في تركيا: جودة عالمية وأسعار تنافسية', type: 'guide', angle: 'medical_beauty' },
  ],
  3: [ // الأربعاء – السياحة العائلية
    { topic: 'أفضل الفنادق العائلية في أنطاليا مع ألعاب مائية', type: 'list', angle: 'family_antalya' },
    { topic: 'نصائح للسفر مع الأطفال إلى تركيا: رحلة مريحة وممتعة', type: 'educational', angle: 'family_tips' },
  ],
  4: [ // الخميس – العروض والخصومات
    { topic: 'خصومات حصرية على حجز السيارات بسائق خاص في بورصة', type: 'promotional', angle: 'transport_offer' },
    { topic: 'باقات شهر العسل 2026: رومانسية في جزر الأمراء', type: 'promotional', angle: 'honeymoon_deals' },
  ],
  5: [ // الجمعة – التراث والثقافة
    { topic: 'أجمل المساجد التاريخية في إسطنبول: عمارة وروحانية', type: 'culture', angle: 'istanbul_mosques' },
    { topic: 'الأسواق الشعبية في تركيا: أين تجد أفضل الهدايا؟', type: 'guide', angle: 'shopping_turkey' },
  ],
  6: [ // السبت – جولات الطبيعة
    { topic: 'رحلة يومية إلى بحيرة صبنجة وشلالات معشوقية', type: 'nature', angle: 'sapanca_tour' },
    { topic: 'جمال الطبيعة في آيدر: استرخاء فوق الغيوم', type: 'nature', angle: 'ayder_clouds' },
  ],
};

const seasonalBonus = [];
if (month >= 6 && month <= 8) { // موسم الصيف
  seasonalBonus.push({ topic: 'انطلق في مغامرة صيفية باردة في الشمال التركي', type: 'seasonal', angle: 'summer_escape' });
}
if (month === 12 || month <= 2) { // موسم الشتاء
  seasonalBonus.push({ topic: 'تزلج في جبل أولوداغ: متعة الشتاء في بورصة', type: 'seasonal', angle: 'winter_ski' });
}

const todayTopics = [...(dayTopics[day] || dayTopics[0]), ...seasonalBonus];
const POSTS_PER_DAY = 2;
const selectedTopics = todayTopics.slice(0, POSTS_PER_DAY);

return selectedTopics.map((t, i) => ({\n  json: {\n    ...t,\n    topic_id: `BLUEVIA-${new Date().toISOString().split('T')[0].replace(/-/g,'')}-${String(i+1).padStart(2,'0')}`,\n    company_name:  'Bluevia Travel',\n    company_url:   'https://blueviatravel.com',\n    whatsapp:      'https://wa.me/{{WHATSAPP_NUMBER}}',\n    service_link:  'https://blueviatravel.com/services',\n    day_index:     day,\n    generated_at:  new Date().toISOString(),\n  }\n}));\n

// ═══════════════════════════════════════════════════════════
// Parse Claude response → build structured posts for GSheets
// ═══════════════════════════════════════════════════════════
const original = $('Split – موضوع واحد في المرة').first().json;
const aiRaw    = $input.first().json;

// استخراج نص الرد من Claude
let rawText = '';
if (typeof aiRaw === 'string') rawText = aiRaw;
else if (aiRaw?.text) rawText = aiRaw.text;
else if (aiRaw?.content?.[0]?.text) rawText = aiRaw.content[0].text;
else if (aiRaw?.output) rawText = aiRaw.output;
else rawText = JSON.stringify(aiRaw);

// تنظيف وparse الـ JSON
let parsed = {};
try {
  const cleaned = rawText
    .replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch(e) {
  // Fallback
  const topic = original.topic || 'Bluevia Travel';
  const link = original.hotel_context?.booking_link || 'wa.me/966XXXXXXXXX';
  parsed = {
    ar_title: topic,
    ar_body: `نحن متخصصون في تقديم أفضل تجارب الإقامة في تركيا. ${topic}`,
    x_post: `🕌 ${topic} | احجز الآن! #فنادق_تركيا #سياحة_تركيا #TurkeyHotel`,
    instagram_post: `🏨 ${topic}\n\n✅ بإطلالة ساحرة\n✅ أسعار مميزة\n📞 احجز الآن!\n#فنادق_تركيا #تركيا_المكرمة #سياحة_تركيا #تركيا2026 #TurkeyHotel`,
    facebook_post: `${topic}\n\nنحن هنا لمساعدتك في اختيار أفضل إقامة في تركيا. اكتب لنا في التعليقات! 👇`,
    whatsapp_broadcast: `السلام عليكم 🌙\n\n${topic}\n\nللحجز وللاستفسار:\n${link}`,
    telegram_post: `🕌 ${topic}\n\nاحجز الآن: ${link}`,
    tiktok_caption: `${topic} 🕌 #فنادق_تركيا #سياحة_تركيا #تركيا #TurkeyHotel #tourism2026`,
    image_prompt_en: `Luxury hotel near Masjid al-Bosphorus Turkey, golden hour, professional photography, 16:9`,
    image_prompt_ar: 'فندق فاخر بإطلالة على آيا صوفيا',
    template_text_ar: topic.substring(0, 35),
    template_subtext_ar: link,
    best_posting_time: '18:00',
    content_score: 70,
    target_emotion: 'trust',
    cta: 'احجز الآن وتمتع بأفضل الأسعار'
  };
}

const now = new Date().toISOString();
const dateStr = now.split('T')[0];
const rowNum = Date.now(); // unique row ID

// SEO hashtags ثابتة
const baseHashtags = '#فنادق_تركيا #حجز_فندق_تركيا #سياحة_تركيا #تركيا2026 #TurkeyHotel #TourismHotel2026 #HotelNearBosphorus #تركيا_المكرمة';

// بناء سجل واحد شامل للـ Sheet
return [{
  json: {
    // ── معرفات ──────────────────────────────────────────────
    row_number:          rowNum,
    topic_id:            original.topic_id,
    topic:               original.topic,
    content_type:        original.content_type,
    angle:               original.angle,

    // ── معلومات عامة ────────────────────────────────────────
    ar_title:            parsed.ar_title    || original.topic,
    ar_body:             parsed.ar_body     || '',
    target_emotion:      parsed.target_emotion || 'trust',
    cta:                 parsed.cta         || 'احجز الآن',

    // ── نصوص المنصات ────────────────────────────────────────
    x_post:              (parsed.x_post             || '').substring(0, 270),
    instagram_post:      parsed.instagram_post       || '',
    facebook_post:       parsed.facebook_post        || '',
    whatsapp_broadcast:  parsed.whatsapp_broadcast   || '',
    telegram_post:       parsed.telegram_post        || '',
    tiktok_caption:      (parsed.tiktok_caption      || '').substring(0, 200),
    seo_hashtags:        baseHashtags,

    // ── الصورة ──────────────────────────────────────────────
    image_prompt_ar:     parsed.image_prompt_ar     || '',
    image_prompt_en:     parsed.image_prompt_en     || '',
    template_text_ar:    parsed.template_text_ar    || '',
    template_subtext_ar: parsed.template_subtext_ar || '',
    image_status:        'pending',        // سيُحدَّث بـ F8 بعد توليد الصورة
    image_url:           '',               // سيُملأ بـ F8

    // ── جدولة ────────────────────────────────────────────────
    content_score:       parseInt(parsed.content_score || 70),
    best_posting_time:   parsed.best_posting_time || '18:00',
    platforms:           (original.platforms || []).join(','),

    // ── حالة النشر ──────────────────────────────────────────
    status:              'ready_to_publish',  // F8 يسحب هذه الحالة
    generated_at:        now,
    published_at:        '',
    published_on:        '',
    publish_attempts:    0,

    // ── معلومات الفندق ────────────────────────────────────────
    company_name:    original.hotel_context?.name    || '',
    booking_link:  original.hotel_context?.booking_link || '',
    company_phone:   original.hotel_context?.phone   || '',
  }
}];

